import torch


def run(x):
    return torch.log10(x.to(torch.float64))


def gen_inputs(ctx, device):
    dtype = getattr(torch, ctx["x__dtype"])
    vals = [0.0, -0.0, 1.0, 10.0, -1.0, float("inf"), float("-inf"), float("nan")]
    return {"x": torch.tensor(vals, dtype=dtype, device=device)}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    ref = ref_outputs[0].detach().to("cpu").to(torch.float64)
    sol = sol_outputs[0].detach()
    sdt = sol.dtype
    sol64 = sol.to("cpu").to(torch.float64)
    if ref.shape != sol64.shape:
        return {"passed": False, "message": f"shape {sol64.shape} vs {ref.shape}", "metrics": {}}
    if sdt == torch.float16:
        rtol, atol = 1e-3, 1e-4
    elif sdt == torch.bfloat16:
        rtol, atol = 1.6e-2, 1e-4
    else:
        rtol, atol = 1.3e-6, 1e-4
    both_nan = torch.isnan(ref) & torch.isnan(sol64)
    both_posinf = torch.isposinf(ref) & torch.isposinf(sol64)
    both_neginf = torch.isneginf(ref) & torch.isneginf(sol64)
    finite = torch.isfinite(ref) & torch.isfinite(sol64)
    close = torch.zeros_like(ref, dtype=torch.bool)
    close[finite] = (ref[finite] - sol64[finite]).abs() <= atol + rtol * ref[finite].abs()
    ok = (close | both_nan | both_posinf | both_neginf).all().item()
    return {"passed": bool(ok), "message": "" if ok else "special-value mismatch", "metrics": {}}
